'use strict';
// 世界模型（/world-models/）的十三个演示。数学都在 wm-models.js（纯函数，tools/wm-test.mjs 测）。wm.js 用 window.MOLASTRIA_WM_DEMOS(K, DEMOS) 把它们登记进去。
// 写法和分子动力学（../md/md-demos.js）一样：title，kind，intro，sel 下拉 [键, 名字, [[值, 名字]…], 初值]，ctl 滑块 [键, 名字, 最小, 最大, 步长, 初值, 写法]，chk 开关 [键, 名字, 初值]，
// btn 预设 [名字, { 键: 值 }]，act 动作，state，autoplay，fps + tick(s)，changed(s, 键)，figs [[高宽比 | 'html', 图注]]，note，draw(s, 图, 颜色) 返回读数 [[名字, 值, 是否加粗]]。
// 读数的值按 HTML 放进页面，只放这里自己算出来的数字和固定的文字。算得慢的结果按参数缓存在 s._c 里。
window.MOLASTRIA_WM_DEMOS = (K, DEMOS) => {
  const M = window.MOLASTRIA_WM_MODELS;
  const { L, fix, fmt, pct, plot, fit, lin, font, esc } = K;
  const memo = (s, slot, key, make) => { s._c ||= {}; if (!s._c[slot] || s._c[slot].key !== key) s._c[slot] = { key, v: make() }; return s._c[slot].v; };
  const lg = (v) => Math.log10(v);

  // ── 1. 学一个单摆的世界模型，再闭着眼睛往前推 ───────────────────────────
  const PEND = [['poly1', L('线性（1 次多项式）', 'Linear (degree-1 polynomial)')], ['poly3', L('3 次多项式', 'Degree-3 polynomial')], ['poly5', L('5 次多项式', 'Degree-5 polynomial')], ['trig', L('物理特征（sin θ、cos θ…）', 'Physics features (sin θ, cos θ, …)')]];
  const pendModel = (kind, box, n, seed) => { const k = kind === 'trig' ? 'trig' : 'poly', deg = kind === 'trig' ? 0 : Number(kind.slice(4)); return M.pendFit(M.pendData(n, box, seed), k, deg); };
  DEMOS.loop = {
    title: L('从数据学一个单摆的“世界模型”，再闭着眼睛往前推', 'Learn a pendulum “world model” from data, then roll it forward with eyes closed'), kind: 'experiment',
    intro: L('世界模型最朴素的定义：给我现在的状态和动作，告诉我下一步会怎样。这里先在一个盒子里随机记下单摆的 (θ, ω, 力矩) 和下一瞬间的状态，用最小二乘拟合一个“下一步 = 这一步 + 特征的线性组合”的模型；然后从一个起点出发，只用模型一步接一步地往前推（开环推演），和真实的单摆比。一步的误差都很小，但误差会累积；起点超出训练数据的范围，或者特征选得不对，推几步就会和真实的轨迹分道扬镳。这和分子动力学里“力场在训练构型之外不可靠”是同一件事。', 'The plainest definition of a world model: given the current state and action, say what happens next. Here we first record random pendulum states (θ, ω, torque) in a box together with the state a moment later, and fit by least squares a model “next = current + a linear combination of features”. Then, from a starting point, we roll forward using only the model, step after step (open-loop rollout), and compare with the real pendulum. Each single step has a tiny error, but errors accumulate; start outside the training range, or choose the wrong features, and the rollout parts company with the truth within a few swings. This is the same thing as “a force field is unreliable outside its training configurations” in molecular dynamics.'),
    sel: [['kind', L('模型', 'Model'), PEND, 'poly3']],
    ctl: [['box', L('训练数据的范围 |θ| ≤', 'Training range |θ| ≤'), 0.4, 3.14, 0.02, 1.2, (v) => `${v.toFixed(2)} rad`], ['th0', L('推演的起点 θ₀', 'Rollout start θ₀'), 0.2, 3.0, 0.05, 1.0, (v) => `${v.toFixed(2)} rad`], ['n', L('训练样本数', 'Training samples'), 30, 1500, 10, 400, String], ['H', L('推演步数（Δt = 0.1）', 'Rollout steps (Δt = 0.1)'), 20, 400, 10, 200, String]],
    btn: [[L('在训练范围里', 'Inside the training range'), { th0: 1, box: 1.2, kind: 'poly3' }], [L('起点超出范围', 'Start outside the range'), { th0: 2.4, box: 1.2, kind: 'poly3' }], [L('换成物理特征', 'Switch to physics features'), { th0: 2.4, box: 1.2, kind: 'trig' }]],
    act: [[L('换一批数据', 'New data'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.5, L('θ(t)：灰线是真实的单摆，彩色线是模型的开环推演；金色的带子是训练数据覆盖的角度。', 'θ(t): grey is the real pendulum, colour the model’s open-loop rollout; the gold band is the range of angles covered by the training data.')], [0.4, L('推演误差 |θ_模型 − θ_真实| 随步数的变化（对数坐标）。', 'Rollout error |θ_model − θ_true| against the number of steps (log scale).')]],
    note: L('真实动力学 θ″ = −sin θ − 0.1 θ′ + u，Δt = 0.1，RK4。训练数据：|θ| ≤ 范围、|ω| ≤ 1.5、|u| ≤ 0.5 里均匀随机取点，每点只记一步。多项式特征是 θᵃωᵇ（a + b ≤ 次数）再加 u；物理特征是 1、sin θ、cos θ、ω、u、sin θ·ω、cos θ·ω、ω²、sin θ cos θ。推演时力矩为 0。真实的世界模型（Dreamer、MuZero）用神经网络，而且多半在潜空间里推演，但“一步准、多步漂、出了训练分布就不可信”这三件事完全一样。', 'True dynamics θ″ = −sin θ − 0.1 θ′ + u, Δt = 0.1, RK4. Training data: uniform random points with |θ| ≤ range, |ω| ≤ 1.5, |u| ≤ 0.5, one step recorded per point. Polynomial features are θᵃωᵇ (a + b ≤ degree) plus u; physics features are 1, sin θ, cos θ, ω, u, sin θ·ω, cos θ·ω, ω², sin θ cos θ. Torque is zero during the rollout. Real world models (Dreamer, MuZero) use neural networks and mostly roll out in a latent space, but the three facts — accurate for one step, drifting over many, untrustworthy outside the training distribution — are exactly the same.'),
    draw(s, [tv, ev], c) {
      const m = memo(s, 'm', `${s.kind}|${s.box}|${s.n}|${s.seed}`, () => pendModel(s.kind, s.box, s.n, s.seed));
      const truth = M.rollout((x, u) => M.pendStep(x, u), [s.th0, 0], s.H), pred = M.rollout((x, u) => M.pendModelStep(m, x, u), [s.th0, 0], s.H);
      const ts = truth.map((_, i) => i * 0.1), lim = Math.max(3.3, s.th0 * 1.15);
      plot(tv, { x: [0, s.H * 0.1], y: [-lim, lim], xl: L('时间 t', 'time t'), yl: 'θ / rad', hbands: [{ y0: -s.box, y1: s.box, color: c.gold, alpha: 0.12 }], series: [{ xs: ts, ys: truth.map((p) => p[0]), color: c.muted, width: 2.6, label: L('真实', 'truth') }, { xs: ts.slice(0, pred.length), ys: pred.map((p) => p[0]), color: c.accent, width: 2, label: L('模型推演', 'model rollout') }] });
      const err = pred.map((p, i) => Math.abs(p[0] - truth[i][0])), errOk = err.map((e) => (Number.isFinite(e) ? Math.max(1e-6, e) : 10));
      plot(ev, { x: [0, s.H], y: [-6, 1.2], logy: true, xl: L('推演步数', 'rollout steps'), yl: '|Δθ|', series: [{ xs: errOk.map((_, i) => i), ys: errOk, color: c.danger, width: 2 }], hmarks: [{ y: 0.1, color: c.gold }] });
      const inBox = M.pendData(200, s.box, 77), wide = M.pendData(200, Math.PI, 78);
      const trust = err.findIndex((e) => !(e < 0.1));
      return [[L('一步误差（训练范围里）', 'One-step error (inside the range)'), fmt(M.oneStepRMSE(m, inBox))], [L('一步误差（全部角度）', 'One-step error (all angles)'), fmt(M.oneStepRMSE(m, wide))], [L('误差超过 0.1 rad 之前能推', 'Steps before the error exceeds 0.1 rad'), trust < 0 ? L(`全部 ${s.H} 步`, `all ${s.H}`) : L(`${trust} 步（t = ${fix(trust * 0.1, 1)}）`, `${trust} (t = ${fix(trust * 0.1, 1)})`), true], [L('起点在训练范围里吗', 'Is the start inside the range'), s.th0 <= s.box ? L('在', 'yes') : L('不在：模型在外推', 'no: the model is extrapolating')]];
    },
  };

  // ── 2. 潜空间：48 个像素的“图像”其实只有两个自由度 ──────────────────────
  DEMOS.pca = {
    title: L('潜空间：48 个像素的图像，其实只由两个数决定', 'Latent space: a 48-pixel image that is really set by two numbers'), kind: 'exact',
    intro: L('每张“图像”是一行 48 个像素上的一个亮斑，只由两个数决定：亮斑的位置和宽度。世界模型的第一步就是把高维的观测压成少数几个潜变量。主成分分析（PCA）是最简单的线性编码器：找方差最大的几个方向，把图像投影上去，再从投影重建。拖动“潜变量个数”，看重建什么时候变好；再看右下的散点：前两个主成分并不是“位置”和“宽度”，同一个位置的图像排成一条弯曲的线。真正的两个自由度躺在一个弯曲的低维流形上，线性的 PCA 要十来个分量才能装下它，这就是 VAE 这类非线性编码器存在的理由。', 'Each “image” is a bright spot on a row of 48 pixels, set by just two numbers: where the spot is and how wide it is. The first step of a world model is to compress high-dimensional observations into a few latent variables. Principal component analysis (PCA) is the simplest linear encoder: find the directions of largest variance, project the image onto them, and reconstruct from the projection. Drag “latent dimensions” to see when the reconstruction becomes good; then look at the scatter plot: the first two principal components are not “position” and “width”, and images with the same width line up along a curve. The two true degrees of freedom lie on a curved low-dimensional manifold, which linear PCA needs a dozen components to hold. That is why nonlinear encoders such as the VAE exist.'),
    sel: [['fac', L('图像的变化', 'What varies'), [['both', L('位置和宽度', 'Position and width')], ['pos', L('只有位置', 'Position only')]], 'both']],
    ctl: [['k', L('潜变量个数 k', 'Latent dimensions k'), 1, 16, 1, 2, String], ['p', L('这张图的亮斑位置', 'Spot position of this image'), 0.15, 0.85, 0.01, 0.42, (v) => v.toFixed(2)], ['w', L('这张图的亮斑宽度', 'Spot width of this image'), 0.035, 0.095, 0.005, 0.05, (v) => v.toFixed(3)]],
    btn: [[L('k = 2（线性压不下）', 'k = 2 (linear is not enough)'), { k: 2 }], [L('k = 8', 'k = 8'), { k: 8 }]],
    figs: [[0.36, L('这一张图（柱子）和用 k 个主成分重建出来的样子（线）。', 'This image (bars) and its reconstruction from k principal components (line).')], [0.38, L('前 k 个主成分解释的方差比例；虚线是 95 %。', 'Fraction of variance explained by the first k components; the dashed line is 95 %.')], [0.5, L('400 张训练图在前两个主成分上的位置，颜色是亮斑的位置。', 'The 400 training images on the first two principal components, coloured by spot position.')]],
    note: L('图像 xᵢ = exp(−½((i + ½)/48 − p)²/w²)，p ∈ [0.15, 0.85]、w ∈ [0.035, 0.095] 均匀随机（“只有位置”时 w = 0.06）。PCA 对 400 张图的协方差矩阵做 Jacobi 本征分解。VAE 把编码器和解码器换成神经网络，并要求潜变量接近标准正态分布，这样潜空间里每一点都能解码出一张合理的图，世界模型才能在潜空间里“做梦”。', 'Images xᵢ = exp(−½((i + ½)/48 − p)²/w²) with p ∈ [0.15, 0.85] and w ∈ [0.035, 0.095] uniform (w = 0.06 for “position only”). PCA is a Jacobi eigendecomposition of the covariance of 400 images. A VAE replaces the encoder and decoder by neural networks and asks the latents to be close to a standard normal distribution, so that every point of latent space decodes to a sensible image and the world model can “dream” in latent space.'),
    draw(s, [iv, ev, zv], c) {
      const D = memo(s, 'p', s.fac, () => { const set = M.blobSet(400, 5, s.fac === 'pos' ? 0.06 : 0); return { set, P: M.pca(set.map((q) => q.x)) }; });
      const x = M.blob(s.p, s.fac === 'pos' ? 0.06 : s.w), z = M.pcaEncode(D.P, x, s.k), xr = M.pcaDecode(D.P, z), idx = x.map((_, i) => i);
      plot(iv, { x: [-0.5, 47.5], y: [-0.25, 1.15], xl: L('像素', 'pixel'), series: [{ xs: idx, ys: x, bars: 0.85, color: c.accent, alpha: 0.35, base: 0 }, { xs: idx, ys: xr, color: c.gold, width: 2.2 }] });
      const ks = lin(1, 16, 16), ex = ks.map((k) => M.explained(D.P, k));
      plot(ev, { x: [0.5, 16.5], y: [0, 1.02], xl: L('潜变量个数 k', 'latent dimensions k'), yl: L('解释的方差', 'variance explained'), series: [{ xs: ks, ys: ex, color: c.accent, dots: 3.5, line: true, width: 2 }], hmarks: [{ y: 0.95, color: c.muted }], marks: [{ x: s.k, y: M.explained(D.P, s.k), color: c.gold }] });
      const Z = D.set.map((q) => M.pcaEncode(D.P, q.x, 2)), zx = Z.map((q) => q[0]), zy = Z.map((q) => q[1]), mx = Math.max(...zx.map(Math.abs), ...zy.map(Math.abs)) * 1.1;
      plot(zv, { x: [-mx, mx], y: [-mx, mx], eq: true, xl: 'PC1', yl: 'PC2', after: ({ ctx, X, Y }) => { D.set.forEach((q, i) => { const h = (q.p - 0.15) / 0.7; ctx.fillStyle = `hsl(${30 + 200 * h} 60% 50%)`; ctx.globalAlpha = 0.75; ctx.beginPath(); ctx.arc(X(zx[i]), Y(zy[i]), 2.6, 0, 2 * Math.PI); ctx.fill(); }); ctx.globalAlpha = 1; const me = M.pcaEncode(D.P, x, 2); ctx.strokeStyle = c.ink; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(X(me[0]), Y(me[1]), 6, 0, 2 * Math.PI); ctx.stroke(); } });
      const need = (f) => ks.find((k) => M.explained(D.P, k) >= f) || '> 16';
      const rms = Math.sqrt(M.mean(x.map((v, i) => (v - xr[i]) ** 2)));
      return [[L('真实的自由度', 'True degrees of freedom'), s.fac === 'pos' ? '1' : '2'], [L('k 个分量解释的方差', 'Variance explained by k'), pct(M.explained(D.P, s.k))], [L('解释 95 % / 99 % 要几个线性分量', 'Linear components for 95 % / 99 %'), `${need(0.95)} / ${need(0.99)}`, true], [L('这张图的重建误差（RMS）', 'Reconstruction error of this image (RMS)'), fmt(rms)]];
    },
  };

  // ── 3. 卡尔曼滤波：一边看一边改的“信念”，看不见以后就只能做梦 ──────────────
  DEMOS.kalman = {
    title: L('卡尔曼滤波：一边观测一边修正的信念，观测停了就只能“做梦”', 'The Kalman filter: a belief corrected by each observation, and only a “dream” once observations stop'), kind: 'exact',
    intro: L('潜空间世界模型（PlaNet、Dreamer 的 RSSM）的祖先是状态空间模型和卡尔曼滤波：心里有一个对隐藏状态的估计和它的不确定度，每来一个观测就按贝叶斯公式修正。这里一个粒子做带随机加速度的匀速运动，我们只看到含噪声的位置。蓝色是滤波的估计和 ±2σ 的带子，比单个观测准得多，还顺便估出了看不见的速度。竖线以后观测停了，模型只能用自己的动力学往前推：带子迅速张开，这就是“在想象里推演”的不确定度。', 'The ancestor of latent world models (the RSSM of PlaNet and Dreamer) is the state-space model and the Kalman filter: keep an estimate of the hidden state and its uncertainty, and correct it with Bayes’ rule each time an observation arrives. Here a particle moves at roughly constant velocity with random accelerations, and we see only noisy positions. Blue is the filter’s estimate with a ±2σ band, far better than any single observation, and it also estimates the unseen velocity. After the vertical line the observations stop and the model can only push forward with its own dynamics: the band opens quickly. That is the uncertainty of “rolling out in imagination”.'),
    ctl: [['lq', L('过程噪声 q（随机加速度的强度）', 'Process noise q (strength of random acceleration)'), -3, 0, 0.1, -1.3, (v) => fmt(10 ** v)], ['r', L('观测噪声 r', 'Observation noise r'), 0.05, 2, 0.05, 0.5, (v) => v.toFixed(2)], ['stop', L('观测在第几步停', 'Observations stop at step'), 20, 200, 5, 140, String]],
    btn: [[L('观测很准', 'Precise observations'), { r: 0.1 }], [L('观测很差', 'Poor observations'), { r: 1.6 }]],
    act: [[L('换一条轨迹', 'New trajectory'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.5, L('位置：灰线是真实位置，点是观测，蓝线和带子是卡尔曼估计 ±2σ。', 'Position: grey is the true position, dots are observations, blue line and band are the Kalman estimate ±2σ.')], [0.3, L('估计的标准差 σ 随时间的变化。', 'Standard deviation σ of the estimate over time.')]],
    note: L('状态 [位置, 速度]，Δt = 0.1，连续白噪声加速度模型：Q = q[[Δt³/3, Δt²/2], [Δt²/2, Δt]]；观测只有位置，方差 r²。线性高斯模型下卡尔曼滤波是精确的贝叶斯后验，也是均方误差最小的估计。稳态增益由 Riccati 方程迭代到收敛得到。Dreamer 的 RSSM 把它换成神经网络：确定性的循环状态加随机的潜变量，用变分推断代替这里的闭式更新。', 'State [position, velocity], Δt = 0.1, continuous white-noise acceleration: Q = q[[Δt³/3, Δt²/2], [Δt²/2, Δt]]; only position is observed, with variance r². For a linear Gaussian model the Kalman filter is the exact Bayesian posterior and the minimum-mean-squared-error estimate. The steady-state gain comes from iterating the Riccati equation to convergence. Dreamer’s RSSM replaces all this with neural networks: a deterministic recurrent state plus stochastic latents, with variational inference instead of the closed-form update.'),
    draw(s, [pv, sv], c) {
      const q = 10 ** s.lq, run = memo(s, 'k', `${s.lq}|${s.r}|${s.stop}|${s.seed}`, () => M.kalmanRun({ q, r: s.r, stop: s.stop, seed: s.seed }));
      const ts = run.map((o) => o.t), all = run.flatMap((o) => [o.x[0], o.m[0] + 2 * o.sd, o.m[0] - 2 * o.sd]).filter(Number.isFinite);
      const lo = Math.min(...all), hi = Math.max(...all), pad = 0.08 * (hi - lo || 1), tStop = s.stop * 0.1;
      plot(pv, { x: [0, 20], y: [lo - pad, hi + pad], xl: L('时间', 'time'), yl: L('位置', 'position'), bands: [{ x0: tStop, x1: 20, color: c.violet, alpha: 0.06 }], marks: [{ x: tStop, color: c.violet }], series: [{ xs: ts, ys: run.map((o) => o.y), dots: 1.8, color: c.muted, alpha: 0.7 }, { xs: ts, ys: run.map((o) => o.x[0]), color: c.ink2, width: 1.6 }, { xs: ts, ys: run.map((o) => o.m[0]), color: c.info, width: 2.2 }], after: ({ ctx, X, Y }) => { ctx.globalAlpha = 0.18; ctx.fillStyle = c.info; ctx.beginPath(); run.forEach((o, i) => { const f = i ? 'lineTo' : 'moveTo'; ctx[f](X(o.t), Y(o.m[0] + 2 * o.sd)); }); for (let i = run.length - 1; i >= 0; i--) ctx.lineTo(X(run[i].t), Y(run[i].m[0] - 2 * run[i].sd)); ctx.closePath(); ctx.fill(); ctx.globalAlpha = 1; } });
      plot(sv, { x: [0, 20], y: [0, Math.max(...run.map((o) => o.sd)) * 1.1], xl: L('时间', 'time'), yl: 'σ', marks: [{ x: tStop, color: c.violet }], series: [{ xs: ts, ys: run.map((o) => o.sd), color: c.info, width: 2 }] });
      const obs = run.slice(10, s.stop), rmseF = Math.sqrt(M.mean(obs.map((o) => (o.m[0] - o.x[0]) ** 2))), rmseY = Math.sqrt(M.mean(obs.map((o) => (o.y - o.x[0]) ** 2)));
      return [[L('滤波估计的误差（RMS）', 'Error of the filtered estimate (RMS)'), fmt(rmseF), true], [L('单个观测的误差（RMS）', 'Error of a single observation (RMS)'), fmt(rmseY)], [L('稳态卡尔曼增益（Riccati）', 'Steady-state Kalman gain (Riccati)'), fix(M.kalmanSteady({ q, r: s.r }), 4)], [L('“做梦”结束时的 σ', 'σ at the end of the “dream”'), fmt(run[run.length - 1].sd)]];
    },
  };

  // ── 4. Dyna-Q：每走一步，在模型里再想 n 步 ─────────────────────────────
  DEMOS.dyna = {
    title: L('Dyna-Q：每在真实世界里走一步，就在学到的模型里再“想” n 步', 'Dyna-Q: for every real step, “think” n more steps inside the learned model'), kind: 'toy',
    intro: L('Sutton 1991 年的 Dyna 是“在想象里学”最早的形式：智能体一边走迷宫一边记下“在哪、做了什么、到了哪、得了什么奖励”，这本小账就是它的世界模型；每走一步真实的步，它再从账本里随机挑 n 条经历重放，更新价值。n = 0 是普通的 Q 学习。看左图：同样的真实经验，n = 50 的智能体第三个回合就几乎走出了最短路，n = 0 的要几十个回合。真实实验（合成、表征、计算）都很贵，这正是化学里想要世界模型的原因。', 'Sutton’s Dyna (1991) is the earliest form of “learning in imagination”: while walking the maze the agent records “where it was, what it did, where it ended up, what reward it got”, and this little ledger is its world model; after each real step it replays n randomly chosen experiences from the ledger to update its values. n = 0 is plain Q-learning. Look at the left plot: from the same real experience the n = 50 agent finds an almost-shortest path by the third episode, while n = 0 needs dozens. Real experiments (synthesis, characterisation, computation) are expensive, which is exactly why chemistry wants world models.'),
    sel: [['n', L('右图显示哪个智能体', 'Agent shown on the right'), [['0', L('n = 0（只用真实经验）', 'n = 0 (real experience only)')], ['5', 'n = 5'], ['50', 'n = 50']], '50']],
    ctl: [['ep', L('回合数', 'Episodes'), 5, 50, 1, 30, String], ['runs', L('平均几次独立的运行', 'Independent runs averaged'), 1, 20, 1, 10, String], ['show', L('右图：第几个回合以后的贪心路径', 'Right: greedy path after episode'), 1, 50, 1, 3, String]],
    act: [[L('换一组随机数', 'New random seeds'), (s) => { s.seed = (s.seed || 1) + 1000; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.45, L('每个回合走了多少步（几次运行的平均）。虚线是最短路 14 步。', 'Steps per episode (mean over runs). The dashed line is the shortest path, 14 steps.')], [0.66, L('迷宫（6 × 9，Sutton 和 Barto 书里的那一个）：S 起点，G 终点；金线是当时的贪心路径。', 'The maze (6 × 9, the one in Sutton and Barto’s book): S start, G goal; the gold line is the greedy path at that point.')]],
    note: L('ε = 0.1 的 ε-贪心，学习率 α = 0.1，折扣 γ = 0.95，到终点奖励 1，其余 0。确定性的环境，所以模型就是一张“(状态, 动作) → (下一状态, 奖励)”的表。智能体走 n 步规划用的是同一个 Q 学习更新，只是经历来自模型而不是环境。环境一变（比如墙挪了），旧模型会误导它，这时需要探索奖励（Dyna-Q+）。', 'ε-greedy with ε = 0.1, learning rate α = 0.1, discount γ = 0.95, reward 1 at the goal and 0 elsewhere. The environment is deterministic, so the model is just a table “(state, action) → (next state, reward)”. The n planning steps use the same Q-learning update, only with experience drawn from the model instead of the environment. When the environment changes (a wall moves, say), the old model misleads the agent, and an exploration bonus is needed (Dyna-Q+).'),
    draw(s, [cv, mv], c) {
      const curves = memo(s, 'cur', `${s.ep}|${s.runs}|${s.seed}`, () => ({ 0: M.dynaAverage(0, s.ep, s.runs, s.seed), 5: M.dynaAverage(5, s.ep, s.runs, s.seed), 50: M.dynaAverage(50, s.ep, s.runs, s.seed) }));
      const xs = curves[0].map((_, i) => i + 1), top = Math.min(1200, Math.max(...curves[0]) * 1.05);
      plot(cv, { x: [1, s.ep], y: [0, top], xl: L('回合', 'episode'), yl: L('步数', 'steps'), series: [{ xs, ys: curves[0], color: c.muted, width: 2, label: 'n = 0' }, { xs, ys: curves[5], color: c.info, width: 2, label: 'n = 5' }, { xs, ys: curves[50], color: c.accent, width: 2.4, label: 'n = 50' }], hmarks: [{ y: 14, color: c.gold }] });
      const one = memo(s, 'one', `${s.n}|${s.show}|${s.seed}`, () => M.dynaQ({ n: Number(s.n), episodes: s.show, seed: s.seed }));
      const path = M.greedyPath(one.Q);
      const { ctx, w, h } = fit(mv), Z = M.MAZE, cell = Math.min((w - 20) / Z.cols, (h - 20) / Z.rows), ox = (w - cell * Z.cols) / 2, oy = (h - cell * Z.rows) / 2;
      for (let r = 0; r < Z.rows; r++) for (let q = 0; q < Z.cols; q++) { const wall = Z.walls.includes(`${r},${q}`); ctx.fillStyle = wall ? c.ink2 : c.surface; ctx.fillRect(ox + q * cell + 1, oy + r * cell + 1, cell - 2, cell - 2); if (!wall) { const v = Math.max(...one.Q[r * Z.cols + q]); ctx.globalAlpha = Math.min(0.5, v * 0.6); ctx.fillStyle = c.accent; ctx.fillRect(ox + q * cell + 1, oy + r * cell + 1, cell - 2, cell - 2); ctx.globalAlpha = 1; } }
      ctx.strokeStyle = c.gold; ctx.lineWidth = 3; ctx.beginPath(); path.forEach((p, i) => { const X = ox + (p[1] + 0.5) * cell, Y = oy + (p[0] + 0.5) * cell; if (i) ctx.lineTo(X, Y); else ctx.moveTo(X, Y); }); ctx.stroke();
      ctx.fillStyle = c.ink; ctx.font = font(Math.max(12, cell * 0.4), 700); ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('S', ox + (Z.start[1] + 0.5) * cell, oy + (Z.start[0] + 0.5) * cell); ctx.fillText('G', ox + (Z.goal[1] + 0.5) * cell, oy + (Z.goal[0] + 0.5) * cell); ctx.textBaseline = 'alphabetic';
      const reached = path.length && path[path.length - 1][0] === Z.goal[0] && path[path.length - 1][1] === Z.goal[1];
      return [[L('第 2 个回合的步数：n = 0 / 5 / 50', 'Steps in episode 2: n = 0 / 5 / 50'), s.ep >= 2 ? `${fix(curves[0][1], 0)} / ${fix(curves[5][1], 0)} / ${fix(curves[50][1], 0)}` : '—', true], [L('最短路（广度优先搜索）', 'Shortest path (breadth-first search)'), L(`${M.mazeShortest()} 步`, `${M.mazeShortest()} steps`)], [L('右图的贪心路径', 'Greedy path on the right'), reached ? L(`${path.length - 1} 步到终点`, `${path.length - 1} steps to the goal`) : L('还走不到终点', 'does not reach the goal yet')], [L('右图智能体在模型里想了几次', 'Imagined updates by the agent on the right'), fmt(one.modelUpdates)]];
    },
  };

  // ── 5. 用模型规划：交叉熵法 + 模型预测控制 ──────────────────────────────
  const MPC_MODELS = [['true', L('真实的方程', 'The true equations')], ['near', L('学的模型：只见过 |θ| ≤ 1，3 次多项式', 'Learned: saw only |θ| ≤ 1, degree-3 polynomial')], ['wide', L('学的模型：见过全部角度，5 次多项式', 'Learned: saw all angles, degree-5 polynomial')], ['trig', L('学的模型：全部角度，物理特征', 'Learned: all angles, physics features')]];
  const mpcStep = (kind) => { if (kind === 'true') return (x, u) => M.pendStep(x, u); const m = kind === 'near' ? M.pendFit(M.pendData(800, 1.0, 1), 'poly', 3) : kind === 'wide' ? M.pendFit(M.pendData(800, Math.PI, 1), 'poly', 5) : M.pendFit(M.pendData(800, Math.PI, 1), 'trig', 0); return (x, u) => M.pendModelStep(m, x, u); };
  const mpcFresh = (s) => { s.x = [0.05, 0]; s.traj = [s.x]; s.us = []; s.warm = []; s.plan = null; s.R = M.rng(s.seed || 1); s.step = mpcStep(s.model); };
  DEMOS.mpc = {
    title: L('用模型规划：在脑子里试 256 种推法，只执行最好的第一步', 'Planning with a model: try 256 pushes in your head, execute only the best first one'), kind: 'experiment',
    intro: L('有了世界模型，就能在动手之前先在脑子里试。这里的任务是把一个力矩不够大的单摆甩到正上方：直接推推不上去，得来回荡几次。每一步，规划器（交叉熵法，CEM）在模型里随机试几十种未来 2.5 秒的力矩序列，挑代价最低的几条，围绕它们再试，几轮以后只执行最好那条的第一步，下一步再重新规划。这就是模型预测控制（MPC），PETS、TD-MPC2 都是这个框架。换成“只在下垂附近见过数据”的模型，它在脑子里以为自己能上去，实际上永远到不了顶。', 'With a world model you can try things in your head before acting. The task is to swing up a pendulum whose torque is too weak to push it straight up: it has to rock back and forth a few times. At every step the planner (the cross-entropy method, CEM) tries dozens of random torque sequences 2.5 s into the future inside the model, keeps the cheapest few, samples around them again, and after a few rounds executes only the first action of the best one, then replans at the next step. This is model predictive control (MPC), the framework of PETS and TD-MPC2. Switch to the model that has only seen data near the bottom: in its head it thinks it can make it, but in reality it never reaches the top.'),
    sel: [['model', L('规划用的模型', 'Model used for planning'), MPC_MODELS, 'true']],
    ctl: [['umax', L('最大力矩 |u|', 'Maximum torque |u|'), 0.2, 1.2, 0.05, 0.5, (v) => v.toFixed(2)]],
    btn: [[L('真实方程', 'True equations'), { model: 'true' }], [L('只见过下垂附近', 'Saw only near the bottom'), { model: 'near' }], [L('物理特征', 'Physics features'), { model: 'trig' }]],
    act: [[L('从头再来', 'Start again'), (s) => { s.seed = (s.seed || 1) + 1; mpcFresh(s); }]],
    state: () => ({ seed: 1 }), autoplay: true, fps: 12,
    changed(s, k) { if (!s.traj || k === '' || k === 'model' || k === 'umax') mpcFresh(s); },
    tick(s) {
      if (s.traj.length > 300) return false;
      const plan = M.cemPlan(s.step, s.x, s.warm, { R: s.R, umax: s.umax, N: 64, iters: 4 });
      const u = plan.u[0]; s.x = M.pendStep(s.x, u); s.traj.push(s.x); s.us.push(u); s.warm = plan.u.slice(1); s.plan = plan;
      return true;
    },
    figs: [[0.62, L('单摆。金色是目标（正上方），淡色的线是规划器最后一次在模型里想出来的未来。', 'The pendulum. Gold is the target (straight up); the faint line is the future the planner last imagined inside its model.')], [0.36, L('离正上方的角度 |θ − π| 和力矩 u 随时间的变化。', 'Angle from the top |θ − π| and torque u over time.')]],
    note: L('θ″ = −sin θ − 0.1 θ′ + u，Δt = 0.1。代价 Σ[(θ − π)² + 0.1 ω² + 0.01 u²]（角度按 2π 折回）。CEM：视界 25 步，每轮 64 条，4 轮，取最好的 8 条更新高斯分布的均值和方差，用上一步的计划热启动。三个学到的模型都按第一个演示的做法拟合，各 800 个样本。真实的机器人和自驱实验室里，规划器面对的是有噪声、会漂移的真实世界，要靠频繁的重新规划和模型的不确定度（集成、贝叶斯）来补救。', 'θ″ = −sin θ − 0.1 θ′ + u, Δt = 0.1. Cost Σ[(θ − π)² + 0.1 ω² + 0.01 u²] (angles wrapped by 2π). CEM: horizon 25 steps, 64 samples per round, 4 rounds, the best 8 update the mean and variance of a Gaussian, warm-started from the previous plan. The three learned models are fitted as in the first demo, 800 samples each. On real robots and in self-driving labs the planner faces a noisy, drifting real world, and frequent replanning and model uncertainty (ensembles, Bayesian models) have to make up for it.'),
    draw(s, [pv, tv], c) {
      const { ctx, w, h } = fit(pv), cx = w / 2, cy = h / 2, Lr = Math.min(w, h) * 0.38;
      const at = (t) => [cx + Lr * Math.sin(t), cy + Lr * Math.cos(t)];
      ctx.strokeStyle = c.line; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(cx, cy, Lr, 0, 2 * Math.PI); ctx.stroke();
      const top = at(Math.PI); ctx.fillStyle = c.gold; ctx.globalAlpha = 0.35; ctx.beginPath(); ctx.arc(top[0], top[1], 14, 0, 2 * Math.PI); ctx.fill(); ctx.globalAlpha = 1;
      if (s.plan) { let x = s.x; ctx.strokeStyle = c.violet; ctx.globalAlpha = 0.5; ctx.lineWidth = 1.5; ctx.beginPath(); for (let i = 0; i < s.plan.u.length; i++) { x = s.step(x, s.plan.u[i]); if (!Number.isFinite(x[0])) break; const p = at(x[0]); if (i) ctx.lineTo(p[0], p[1]); else ctx.moveTo(p[0], p[1]); } ctx.stroke(); ctx.globalAlpha = 1; }
      const p = at(s.x[0]); ctx.strokeStyle = c.ink; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(p[0], p[1]); ctx.stroke();
      ctx.fillStyle = c.accent; ctx.beginPath(); ctx.arc(p[0], p[1], 11, 0, 2 * Math.PI); ctx.fill(); ctx.fillStyle = c.ink2; ctx.beginPath(); ctx.arc(cx, cy, 4, 0, 2 * Math.PI); ctx.fill();
      const ts = s.traj.map((_, i) => i * 0.1), dev = s.traj.map((x) => Math.abs(M.wrap(x[0] - Math.PI)));
      plot(tv, { x: [0, 30], y: [-1.3, 3.3], xl: L('时间', 'time'), series: [{ xs: ts, ys: dev, color: c.accent, width: 2, label: '|θ − π|' }, { xs: ts.slice(1), ys: s.us.map((u) => u / s.umax), color: c.muted, width: 1.2, label: 'u / uₘₐₓ' }], hmarks: [{ y: 0.25, color: c.gold }] });
      const up = M.upTime(s.traj);
      return [[L('时间', 'Time'), fix((s.traj.length - 1) * 0.1, 1)], [L('离正上方', 'From the top'), `${fix(dev[dev.length - 1], 2)} rad`], [L('稳在正上方的时刻', 'Time it settled at the top'), Number.isFinite(up) ? `t = ${fix(up, 1)}` : L('还没有', 'not yet'), true], [L('规划器以为的代价', 'Cost the planner expects'), s.plan ? fmt(s.plan.J) : '—']];
    },
  };

  // ── 6. 预测像素还是预测表示 ─────────────────────────────────────────────
  DEMOS.jepa = {
    title: L('预测像素还是预测表示：噪声预测不了，表示会塌缩', 'Predict pixels or predict representations: noise cannot be predicted, and representations can collapse'), kind: 'experiment',
    intro: L('观测是 8 维的，里面藏着 1 个慢慢变的量（金线），其余 7 个方向全是每一步都换的噪声，再用一个随机的转动混在一起。直接预测下一帧的“像素”：最好的线性预测器也只能解释一小部分方差，因为噪声本来就预测不了，它却占了大部分误差。JEPA 的思路是先编码成表示 z = w·x，再在表示空间里预测 z 的下一步。但如果只让“预测误差”变小，最省事的解是 w → 0：表示塌缩成常数，预测误差为零，什么也没学到。加一项让 z 的方差不小于 1（VICReg 的方差项），编码器就被逼着找到那个慢变量。', 'The observation is 8-dimensional; one slowly varying quantity (gold) hides in it, the other 7 directions are noise that changes every step, and a random rotation mixes them. Predict the next frame’s “pixels” directly and even the best linear predictor explains only a small fraction of the variance: the noise is unpredictable by nature, yet it accounts for most of the error. JEPA instead encodes the observation into a representation z = w·x and predicts the next z in representation space. But if only the prediction error is minimised, the laziest solution is w → 0: the representation collapses to a constant, the prediction error is zero and nothing has been learned. Add a term that keeps the variance of z at least 1 (the variance term of VICReg) and the encoder is forced to find the slow variable.'),
    sel: [['reg', L('防塌缩的项', 'Anti-collapse term'), [['0', L('没有（只最小化预测误差）', 'None (prediction error only)')], ['1', L('方差项 max(0, 1 − std z)²', 'Variance term max(0, 1 − std z)²')]], '0']],
    ctl: [['noise', L('噪声的强度 σ', 'Noise strength σ'), 0.2, 3, 0.1, 1, (v) => v.toFixed(1)], ['iters', L('梯度下降的步数', 'Gradient steps'), 50, 1200, 50, 600, String]],
    btn: [[L('没有防塌缩', 'No anti-collapse'), { reg: '0' }], [L('加方差项', 'With variance term'), { reg: '1' }]],
    act: [[L('换一组数据', 'New data'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.42, L('训练过程：预测误差（蓝）和表示的标准差 std z（紫），对数坐标。', 'Training: prediction error (blue) and the representation’s standard deviation std z (violet), log scale.')], [0.4, L('前 400 步：金线是藏着的慢变量，蓝线是学到的表示 z（为了比较放大到同样的方差）。', 'First 400 steps: gold is the hidden slow variable, blue is the learned representation z (rescaled to the same variance for comparison).')]],
    note: L('x_t = Q[s_t, σn_t]，s 是 φ = 0.98 的 AR(1)，n 是 7 维标准正态，Q 是随机正交矩阵，2000 步。像素预测：x_{t+1} 对 x_t 的线性回归。表示预测：z = w·x，预测器固定为恒等（z_{t+1} ≈ z_t），学习率 0.1。没有方差项时 w 的每个方向都按 (1 − 0.2 var(w·Δx)) 指数衰减，慢方向衰减得最慢，所以方向是对的，但尺度趋于零，在有限精度和真实网络里就是塌缩。I-JEPA 和 V-JEPA 用的是另一种防塌缩办法：目标编码器是在线编码器的指数滑动平均，并且不传梯度。慢特征分析（SFA）在 var z = 1 的约束下直接解出同一个方向。', 'x_t = Q[s_t, σn_t] with s an AR(1) of φ = 0.98, n 7-dimensional standard normal, Q a random orthogonal matrix, 2000 steps. Pixel prediction: linear regression of x_{t+1} on x_t. Representation prediction: z = w·x with the predictor fixed to the identity (z_{t+1} ≈ z_t), learning rate 0.1. Without the variance term every direction of w decays like (1 − 0.2 var(w·Δx))ᵗ and the slow direction decays slowest, so the direction is right but the scale goes to zero — in finite precision and in real networks, that is collapse. I-JEPA and V-JEPA prevent collapse differently: the target encoder is an exponential moving average of the online encoder and receives no gradient. Slow feature analysis (SFA) solves for the same direction directly under the constraint var z = 1.'),
    draw(s, [lv, zv], c) {
      const D = memo(s, 'd', `${s.noise}|${s.seed}`, () => { const d = M.jepaData({ noise: s.noise, seed: s.seed }); return { ...d, r2: M.pixelR2(d.X), sfa: M.sfa(d.X) }; });
      const tr = memo(s, 't', `${s.noise}|${s.seed}|${s.reg}|${s.iters}`, () => M.jepaTrain(D.X, { reg: Number(s.reg), iters: s.iters }));
      const H = tr.hist, ys = H.flatMap((q) => [q.pred, q.sd]).filter((v) => v > 0);
      plot(lv, { x: [0, s.iters], y: [Math.floor(lg(Math.min(...ys))), Math.ceil(lg(Math.max(...ys)) + 0.2)], logy: true, xl: L('梯度下降的步数', 'gradient steps'), series: [{ xs: H.map((q) => q.it), ys: H.map((q) => q.pred), color: c.info, width: 2, label: L('预测误差', 'prediction error') }, { xs: H.map((q) => q.it), ys: H.map((q) => q.sd), color: c.violet, width: 2, label: 'std z' }], hmarks: [{ y: 1, color: c.muted }] });
      const n = 400, sd = Math.sqrt(M.variance(tr.z)) || 1, sgn = Math.sign(M.corr(tr.z, D.s)) || 1, zs = tr.z.slice(0, n).map((v) => (sgn * v) / sd);
      plot(zv, { x: [0, n], y: [-3.2, 3.2], xl: L('时间步', 'time step'), series: [{ xs: lin(0, n - 1, n), ys: D.s.slice(0, n), color: c.gold, width: 2.4 }, { xs: lin(0, n - 1, n), ys: zs, color: c.info, width: 1.6 }] });
      const zt = tr.z, lat = M.corr(zt.slice(1), zt.slice(0, -1)) ** 2, last = H[H.length - 1];
      return [[L('像素预测能解释的方差 R²', 'Variance explained by pixel prediction R²'), pct(D.r2)], [L('表示预测的 R²（z 对自己下一步）', 'R² of representation prediction (z on its next step)'), pct(lat)], [L('表示的标准差 std z', 'Standard deviation std z'), fmt(last.sd), true], [L('|corr(z, 慢变量)|：梯度下降 / SFA', '|corr(z, slow variable)|: gradient descent / SFA'), `${fix(Math.abs(M.corr(zt, D.s)), 3)} / ${fix(Math.abs(M.corr(D.X.map((x) => M.dot(D.sfa, x)), D.s)), 3)}`], [L('结论', 'Verdict'), last.sd < 0.05 ? L('塌缩了：表示几乎是常数', 'collapsed: the representation is almost constant') : L('没有塌缩', 'not collapsed')]];
    },
  };

  // ── 7. 潜在动作：只看视频，找回按键 ────────────────────────────────────
  DEMOS.lam = {
    title: L('潜在动作：只看视频、不知道按了什么键，也能找回“动作”', 'Latent actions: recover the “actions” from video alone, without knowing which keys were pressed'), kind: 'toy',
    intro: L('Genie 从网上没有标注的游戏视频里学交互式世界模型，关键一步是“潜在动作模型”：看相邻两帧，推断中间发生了什么动作，再把动作压成少数几个离散的码。这里一个亮点在 8 × 12 的画面里按上、下、左、右、不动五种动作走，画面上撒着噪声；我们只把相邻两帧的亮度重心位移拿出来，用 k-means 分成 K 类，再和真实的按键对照。噪声小、K = 5 时，五个簇几乎正好是五个键；撞墙没动的那几步和“不动”分不开，这是从视频推动作的本质困难：看不见的意图只能从看得见的后果推。', 'Genie learns an interactive world model from unlabelled game videos on the internet, and the key step is a “latent action model”: look at two consecutive frames, infer what action happened in between, and compress actions into a few discrete codes. Here a bright spot moves on an 8 × 12 screen by five actions (up, down, left, right, stay) with noise sprinkled on the image; we take only the displacement of the brightness centroid between consecutive frames, split it into K clusters by k-means, and compare with the true keys. With little noise and K = 5 the five clusters are almost exactly the five keys; the steps where the spot hit a wall and did not move are indistinguishable from “stay”. That is the essential difficulty of inferring actions from video: invisible intentions can only be read from visible consequences.'),
    ctl: [['noise', L('画面噪声', 'Image noise'), 0, 0.6, 0.02, 0.15, (v) => v.toFixed(2)], ['K', L('潜在动作的个数 K', 'Number of latent actions K'), 2, 8, 1, 5, String], ['T', L('视频长度（帧）', 'Video length (frames)'), 100, 800, 50, 400, String]],
    btn: [[L('干净的视频', 'Clean video'), { noise: 0.05, K: 5 }], [L('噪声很大', 'Very noisy'), { noise: 0.45 }], [L('K = 3（码不够用）', 'K = 3 (too few codes)'), { K: 3, noise: 0.1 }]],
    act: [[L('换一段视频', 'New video'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.2, L('视频的前八帧（每帧下面是 k-means 给它和下一帧之间分的潜在动作编号）。', 'The first eight frames (under each is the latent action k-means assigns between it and the next frame).')], [0.6, L('每一对相邻帧的特征：亮度重心的位移 (Δ列, Δ行)，颜色是分到的簇。', 'Feature of each pair of frames: the displacement of the brightness centroid (Δcolumn, Δrow), coloured by cluster.')], ['html', L('真实的键（列）和潜在动作（行）的对照表。', 'Cross-table of true keys (columns) and latent actions (rows).')]],
    note: L('五种动作等概率，撞墙就停在原地。每帧：亮点 1，周围八格 0.45，再加 [0, 噪声) 的均匀噪声。特征：减去画面平均亮度后的亮度重心，两帧相减。k-means++ 初始化，50 轮。纯度 = 每个簇按它里面最多的那个真实动作算对的比例（撞墙没动的步按“不动”算）。Genie 的潜在动作模型是一个视频 Transformer 加向量量化（VQ），码本只有 8 个，而且是和“用动作重建下一帧”一起训练的；这里用手写的特征代替了它学到的特征。', 'Five actions with equal probability; hitting a wall leaves the spot in place. Each frame: the spot is 1, its eight neighbours 0.45, plus uniform noise in [0, noise). Feature: the brightness centroid after subtracting the mean brightness, differenced between frames. k-means++ initialisation, 50 rounds. Purity = fraction counted correct when each cluster is assigned its most common true action (steps blocked by a wall count as “stay”). Genie’s latent action model is a video transformer with vector quantisation (VQ), a codebook of only 8, trained jointly with “reconstruct the next frame from the action”; a hand-written feature stands in for its learned features here.'),
    draw(s, [fv, sv, tv], c) {
      const V = memo(s, 'v', `${s.noise}|${s.T}|${s.seed}`, () => { const v = M.laVideo({ T: s.T, noise: s.noise, seed: s.seed }); return { ...v, F: v.frames.slice(1).map((f, i) => M.laFeature(v.frames[i], f)) }; });
      const km = memo(s, 'k', `${s.noise}|${s.T}|${s.seed}|${s.K}`, () => M.kmeans(V.F, s.K, s.seed));
      const pal = [c.accent, c.gold, c.info, c.violet, c.danger, c.ok, c.warn, c.ink2];
      const { ctx, w, h } = fit(fv), nF = 8, gap = 6, fw = (w - gap * (nF - 1)) / nF, cs = Math.min(fw / M.LA.cols, (h - 18) / M.LA.rows);
      for (let k = 0; k < nF; k++) { const f = V.frames[k], ox = k * (fw + gap); for (let i = 0; i < f.length; i++) { const r = Math.floor(i / M.LA.cols), q = i % M.LA.cols; ctx.globalAlpha = Math.min(1, f[i]); ctx.fillStyle = c.ink; ctx.fillRect(ox + q * cs, r * cs, cs, cs); } ctx.globalAlpha = 1; ctx.strokeStyle = c.line; ctx.strokeRect(ox, 0, cs * M.LA.cols, cs * M.LA.rows); if (k < nF - 1) { ctx.fillStyle = pal[km.lab[k] % pal.length]; ctx.font = font(11, 700); ctx.textAlign = 'center'; ctx.fillText(`z${km.lab[k] + 1}`, ox + (cs * M.LA.cols) / 2, cs * M.LA.rows + 13); } }
      plot(sv, { x: [-1.6, 1.6], y: [-1.6, 1.6], eq: true, xl: L('Δ列', 'Δcolumn'), yl: L('Δ行', 'Δrow'), after: ({ ctx: g, X, Y }) => { V.F.forEach((p, i) => { g.fillStyle = pal[km.lab[i] % pal.length]; g.globalAlpha = 0.6; g.beginPath(); g.arc(X(p[1]), Y(-p[0]), 2.6, 0, 2 * Math.PI); g.fill(); }); g.globalAlpha = 1; km.cen.forEach((q, k) => { g.strokeStyle = c.ink; g.lineWidth = 2; g.beginPath(); g.arc(X(q[1]), Y(-q[0]), 7, 0, 2 * Math.PI); g.stroke(); g.fillStyle = c.ink; g.font = font(11, 700); g.fillText(`z${k + 1}`, X(q[1]) + 9, Y(-q[0]) - 6); }); } });
      const P = M.laPurity(km.lab, V.acts, s.K), names = [L('上', 'up'), L('下', 'down'), L('左', 'left'), L('右', 'right'), L('不动 / 撞墙', 'stay / wall')];
      tv.innerHTML = `<table class="mdf-peaks"><thead><tr><th>${esc(L('潜在动作', 'Latent action'))}</th>${names.map((x) => `<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${P.tab.map((row, k) => `<tr><td><span class="mdf-swatch" style="background:${pal[k % pal.length]}"></span> z${k + 1}</td>${row.map((v) => `<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
      const blocked = V.acts.filter((a) => !a.moved && a.a !== 4).length;
      return [[L('纯度', 'Purity'), pct(P.purity), true], [L('撞墙没动的步数', 'Steps blocked by a wall'), `${blocked} / ${V.acts.length}`], [L('真实的键有几种', 'Number of true keys'), '5']];
    },
  };

  // ── 8. DMD：从快照里学一个线性的世界模型 ───────────────────────────────
  DEMOS.dmd = {
    title: L('动态模态分解：从快照里学一个线性的世界模型，读出每个模的衰减和频率', 'Dynamic mode decomposition: learn a linear world model from snapshots and read off each mode’s decay and frequency'), kind: 'exact',
    intro: L('一个场在周期的一维区域里一边平移一边扩散（对流扩散方程）。我们不告诉算法方程是什么，只给它一串等间隔的快照。DMD 找一个最好的线性算子 A，使下一张快照 ≈ A × 这一张；A 的本征值就是各个模的衰减率和振荡频率，和解析答案 ω = −Dk² ∓ ick 一比就知道学得对不对。秩 r 取到模数的两倍、没有噪声时，本征值准到机器精度；r 不够或者加了噪声，就开始出错。Koopman 理论说，非线性系统换到合适的特征空间里也能这样线性地演化，这是很多“学出来的模拟器”的数学底子。', 'A field in a periodic one-dimensional domain is carried along and spreads out at the same time (the advection–diffusion equation). We do not tell the algorithm the equation; we only give it a series of equally spaced snapshots. DMD finds the best linear operator A such that the next snapshot ≈ A × this one; A’s eigenvalues are the decay rates and oscillation frequencies of the modes, and comparing them with the analytic answer ω = −Dk² ∓ ick tells us whether it learned correctly. With rank r equal to twice the number of modes and no noise, the eigenvalues are right to machine precision; with too small an r or with noise they go wrong. Koopman theory says that a nonlinear system, moved to a suitable feature space, also evolves linearly like this; that is the mathematical basis of many “learned simulators”.'),
    ctl: [['r', L('秩 r', 'Rank r'), 2, 12, 1, 6, String], ['lnoise', L('快照上的噪声（log₁₀）', 'Noise on the snapshots (log₁₀)'), -6, -0.5, 0.25, -6, (v) => (v <= -6 ? L('没有', 'none') : fmt(10 ** v))], ['m', L('快照张数', 'Number of snapshots'), 8, 80, 1, 40, String], ['D', L('扩散系数 D', 'Diffusion coefficient D'), 0, 0.1, 0.005, 0.02, (v) => v.toFixed(3)]],
    btn: [[L('r = 6：正好', 'r = 6: just right'), { r: 6, lnoise: -6 }], [L('r = 4：不够', 'r = 4: too small'), { r: 4, lnoise: -6 }], [L('加噪声', 'Add noise'), { r: 6, lnoise: -1.3 }]],
    act: [[L('换一组初值', 'New initial condition'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.42, L('训练窗口结束后再往前预测同样长的时间：灰线是真实的场，蓝线是 DMD 的预测。', 'Forecast as far again beyond the training window: grey is the true field, blue the DMD forecast.')], [0.55, L('连续时间本征值 ω = ln μ / Δt：横轴是衰减率，纵轴是频率。空心圆是解析值，实心点是 DMD 找到的。', 'Continuous-time eigenvalues ω = ln μ / Δt: decay rate horizontally, frequency vertically. Open circles are analytic values, filled dots what DMD found.')]],
    note: L('u_t + c u_x = D u_xx，c = 1，x ∈ [0, 2π) 上 64 个格点，初值是 k = 1、2、3 三个傅里叶模的随机组合，Δt = 0.1。快照按解析解生成，所以没有数值误差。DMD（Schmid 2010）：X 的薄 SVD（这里对 XᵀX 求本征分解），Ã = UᵀYVΣ⁻¹，Ã 的本征值用复数位移 QR 迭代求。预测在 r 维子空间里走：z ← Ãz。真实流体是非线性的，DMD 只能给出它在一段时间里的最佳线性近似。', 'u_t + c u_x = D u_xx with c = 1 on 64 grid points of [0, 2π); the initial condition is a random combination of Fourier modes k = 1, 2, 3; Δt = 0.1. Snapshots come from the analytic solution, so there is no numerical error. DMD (Schmid 2010): a thin SVD of X (here via the eigendecomposition of XᵀX), Ã = UᵀYVΣ⁻¹, eigenvalues of Ã by complex shifted QR iteration. Forecasts move in the r-dimensional subspace: z ← Ãz. Real fluids are nonlinear, and DMD gives only their best linear approximation over a stretch of time.'),
    draw(s, [fv, ev], c) {
      const noise = s.lnoise <= -6 ? 0 : 10 ** s.lnoise;
      const A = memo(s, 'a', `${s.lnoise}|${s.m}|${s.D}|${s.seed}`, () => M.advdiff({ D: s.D, m: s.m, noise, seed: s.seed }));
      const d = memo(s, 'd', `${s.lnoise}|${s.m}|${s.D}|${s.seed}|${s.r}`, () => M.dmd(A.snaps, s.r, A.dt));
      const steps = s.m, fc = d.predict(A.snaps[s.m], steps), tEnd = 2 * s.m * A.dt, truth = A.at(tEnd), pred = fc[fc.length - 1];
      const amp = Math.max(...truth.map(Math.abs), ...A.snaps[0].map(Math.abs)) * 1.15;
      plot(fv, { x: [0, 2 * Math.PI], y: [-amp, amp], xl: 'x', yl: `u(x, t = ${fix(tEnd, 1)})`, series: [{ xs: A.x, ys: truth, color: c.muted, width: 2.6 }, { xs: A.x, ys: pred.map((v) => Math.max(-3 * amp, Math.min(3 * amp, v))), color: c.info, width: 2 }] });
      const om = d.omega, re = [...om.map((z) => z[0]), ...A.exact.map((z) => z[0])].filter(Number.isFinite), xlo = Math.min(-0.3, ...re) * 1.15;
      plot(ev, { x: [xlo, Math.max(0.15, ...re) + 0.05], y: [-3.8, 3.8], xl: L('衰减率 Re ω', 'decay rate Re ω'), yl: L('频率 Im ω', 'frequency Im ω'), marks: [{ x: 0, color: c.line }], after: ({ ctx, X, Y }) => { ctx.strokeStyle = c.gold; ctx.lineWidth = 2; for (const z of A.exact) { ctx.beginPath(); ctx.arc(X(z[0]), Y(z[1]), 7, 0, 2 * Math.PI); ctx.stroke(); } ctx.fillStyle = c.info; for (const z of om) { if (!Number.isFinite(z[0])) continue; ctx.beginPath(); ctx.arc(X(z[0]), Y(Math.max(-3.8, Math.min(3.8, z[1]))), 3.6, 0, 2 * Math.PI); ctx.fill(); } } });
      const err = Math.sqrt(M.mean(pred.map((v, i) => (v - truth[i]) ** 2))) / Math.sqrt(M.mean(truth.map((v) => v * v)) || 1);
      return [[L('本征值的最大误差', 'Largest eigenvalue error'), fmt(M.eigMatchError(om, A.exact)), true], [L('预测的相对误差', 'Relative forecast error'), pct(err)], [L('真正用上的秩', 'Rank actually used'), `${d.r}`], [L('需要的秩（2 × 模数）', 'Rank needed (2 × number of modes)'), '6']];
    },
  };

  // ── 9. 从力学一个对势：学出来的粒子模拟器在训练分布外会怎样 ─────────────────
  DEMOS.pairfit = {
    title: L('学出来的粒子模拟器：从力学一个对势，再拿去跑更热的分子动力学', 'A learned particle simulator: fit a pair potential to forces, then run hotter molecular dynamics with it'), kind: 'experiment',
    intro: L('图网络模拟器和机器学习势的训练方式几乎一样：拿一批构型和每个原子受的力，让模型学出“构型 → 力”。这里七个 Lennard-Jones 原子在低温下抖动，我们用一组高斯基函数拼一个对势 U(r)，按“力匹配”线性拟合，然后用它跑分子动力学。在训练温度下它和真实的势几乎一样好；把测试温度调高，原子撞得更近，走进训练数据从来没到过的短距离：那里模型没有排斥，原子会塌到一起。打开“物理先验”（加一个已知的 r⁻¹² 排斥，只学剩下的部分），同样的数据就稳了。真实的机器学习势也常这样加一个短程排斥（ZBL）。', 'Graph-network simulators and machine-learned potentials are trained in almost the same way: take a set of configurations and the force on every atom, and let the model learn “configuration → forces”. Here seven Lennard-Jones atoms jiggle at low temperature, we build a pair potential U(r) from Gaussian basis functions, fit it linearly by “force matching”, and then run molecular dynamics with it. At the training temperature it is almost as good as the true potential; raise the test temperature and atoms collide more closely, into short distances the training data never reached: there the model has no repulsion and the atoms collapse together. Switch on the “physics prior” (add a known r⁻¹² repulsion and learn only the rest) and the same data become stable. Real machine-learned potentials often add a short-range repulsion (ZBL) in just this way.'),
    chk: [['prior', L('物理先验：加上已知的 4r⁻¹² 排斥', 'Physics prior: add the known 4r⁻¹² repulsion'), false]],
    ctl: [['Ttr', L('训练数据的温度 kT', 'Training temperature kT'), 0.05, 0.5, 0.05, 0.1, (v) => v.toFixed(2)], ['Tte', L('测试的温度 kT', 'Test temperature kT'), 0.1, 8, 0.1, 0.3, (v) => v.toFixed(1)], ['n', L('训练构型数', 'Training configurations'), 10, 120, 10, 60, String]],
    btn: [[L('训练温度下测试', 'Test at the training temperature'), { Tte: 0.3, prior: false }], [L('热了：塌缩', 'Hot: collapse'), { Tte: 6, prior: false }], [L('热了 + 先验', 'Hot + prior'), { Tte: 6, prior: true }]],
    act: [[L('换一批数据', 'New data'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.45, L('对力 F(r) = −dU/dr：灰线是真实的 Lennard-Jones，蓝线是学到的；柱子是训练数据里原子对距离的分布。', 'Pair force F(r) = −dU/dr: grey is the true Lennard-Jones, blue the learned one; bars show the distribution of pair distances in the training data.')], [0.38, L('测试运行里任意两个原子的最近距离随时间的变化（真实势：灰，学到的势：蓝）。', 'Closest distance between any two atoms during the test run (true potential grey, learned blue).')]],
    note: L('二维，7 个原子，ε = σ = m = 1，半径 2.2 以外有一个软的球形墙。训练：Langevin（γ = 1，Δt = 0.004）在训练温度下平衡，每 40 步取一个构型，记下真实的力。模型：U(r) = 先验 + cut(r) Σ c_k φ_k(r)，φ_k 是中心在 0.9 到 2.6 的 24 个高斯（宽 0.08），cut 让势在 r = 2.8 平滑地归零；力对 c 是线性的，岭回归一步解出。测试：速度 Verlet（Δt = 0.003）跑 2000 步，初速度按测试温度抽；最近距离小于 0.3 就算塌缩。注意力只决定势的斜率：在没有原子对的距离上，学出来的势可以和真实的差一个常数甚至走样，这是“学到的东西只在见过的地方可信”的最小例子。', 'Two dimensions, 7 atoms, ε = σ = m = 1, with a soft spherical wall beyond radius 2.2. Training: Langevin (γ = 1, Δt = 0.004) equilibrated at the training temperature, one configuration every 40 steps with the true forces recorded. Model: U(r) = prior + cut(r) Σ c_k φ_k(r), with φ_k 24 Gaussians centred from 0.9 to 2.6 (width 0.08) and cut bringing the potential smoothly to zero at r = 2.8; the forces are linear in c, so one ridge regression solves it. Test: velocity Verlet (Δt = 0.003) for 2000 steps, initial velocities drawn at the test temperature; a closest distance below 0.3 counts as collapse. Note that forces fix only the slope of the potential: at distances with no pairs, the learned potential can differ from the true one by a constant or worse. This is the smallest example of “what is learned is trustworthy only where it has seen data”.'),
    draw(s, [fv, rv], c) {
      const m = memo(s, 'm', `${s.Ttr}|${s.n}|${s.seed}|${s.prior}`, () => M.pfFit(M.pfTrainData({ T: s.Ttr, n: s.n, seed: s.seed }), s.prior));
      const pair = { u: (r) => M.learnedU(m, r), d: (r) => M.learnedDU(m, r) };
      const run = memo(s, 'r', `${s.Ttr}|${s.n}|${s.seed}|${s.prior}|${s.Tte}`, () => ({ L: M.pfRun(pair, { T: s.Tte, seed: s.seed + 7 }), T: M.pfRun(M.TRUE_PAIR, { T: s.Tte, seed: s.seed + 7 }) }));
      const rs = lin(0.8, 2.7, 200), ed = lin(0.8, 2.7, 39), cnt = new Array(38).fill(0);
      for (const d of m.dists) { const k = Math.floor((d - 0.8) / 0.05); if (k >= 0 && k < 38) cnt[k]++; }
      const cm = Math.max(...cnt) || 1;
      plot(fv, { x: [0.8, 2.7], y: [-4, 30], xl: 'r / σ', yl: 'F(r)', series: [{ xs: ed.slice(0, -1).map((x) => x + 0.025), ys: cnt.map((v) => (v / cm) * 26), bars: 0.045, color: c.gold, alpha: 0.35, base: 0 }, { xs: rs, ys: rs.map((r) => -M.dLJ(r)), color: c.muted, width: 2.6 }, { xs: rs, ys: rs.map((r) => -M.learnedDU(m, r)), color: c.info, width: 2 }], hmarks: [{ y: 0, color: c.line, dash: [] }] });
      const tl = run.L.rec, tt = run.T.rec;
      plot(rv, { x: [0, 6], y: [0, 1.3], xl: L('时间', 'time'), yl: L('最近距离 r_min', 'closest distance r_min'), series: [{ xs: tt.map((q) => q.t), ys: tt.map((q) => q.rmin), color: c.muted, width: 2.4 }, { xs: tl.map((q) => q.t), ys: tl.map((q) => q.rmin), color: c.info, width: 2 }], hmarks: [{ y: m.rmin, color: c.gold }] });
      return [[L('力的拟合误差（训练集 RMS）', 'Force fit error (training RMS)'), fmt(m.rmse)], [L('训练数据里最近的原子对', 'Closest pair in the training data'), `${fix(m.rmin, 3)} σ`], [L('测试中最近的原子对：真实 / 学到', 'Closest pair in the test: true / learned'), `${fix(run.T.rmin, 3)} / ${fix(run.L.rmin, 3)} σ`], [L('学到的势', 'Learned potential'), run.L.collapsed ? L('塌缩了：原子撞到了一起', 'collapsed: atoms ran into each other') : L('稳定', 'stable'), true]];
    },
  };

  // ── 10. SINDy：从轨迹里找回洛伦兹方程，再做集合预报 ──────────────────────
  DEMOS.lorenz = {
    title: L('从数据里找回方程（SINDy），再做集合预报：混沌给可预报性划了上限', 'Recover the equations from data (SINDy), then forecast with an ensemble: chaos caps predictability'), kind: 'experiment',
    intro: L('洛伦兹 1963 年从一个简化的对流模型得到三个方程，也发现了“蝴蝶效应”。SINDy 的做法是：从轨迹算导数，在一个候选函数库（1、x、y、z、x²、xy…）里做稀疏回归，只留下少数几项。没有噪声时，它正好找回七项系数，和真方程一样。然后用找回的方程做集合预报：从二十个只差 ε 的起点出发，一开始它们重合，几个时间单位以后就散开到整个吸引子上。即使模型完美，可预报时间也只随 ln(1/ε) 增长；天气模型（GraphCast、GenCast）面对的正是这个上限，所以 GenCast 输出的是一组可能的未来，而不是一条。', 'In 1963 Lorenz derived three equations from a simplified model of convection and discovered the “butterfly effect”. SINDy computes derivatives from a trajectory, regresses them sparsely on a library of candidate functions (1, x, y, z, x², xy, …) and keeps only a few terms. Without noise it recovers exactly the seven coefficients of the true equations. We then forecast with the recovered equations as an ensemble: twenty starting points differing by ε coincide at first and spread over the whole attractor after a few time units. Even with a perfect model the predictable time grows only like ln(1/ε). Weather models (GraphCast, GenCast) face exactly this cap, which is why GenCast outputs a set of possible futures rather than one.'),
    ctl: [['noise', L('轨迹上的测量噪声', 'Measurement noise on the trajectory'), 0, 0.5, 0.01, 0, (v) => v.toFixed(2)], ['lth', L('稀疏阈值（log₁₀）', 'Sparsity threshold (log₁₀)'), -3, 0.5, 0.05, -1, (v) => fmt(10 ** v)], ['leps', L('集合的初始扰动 ε（log₁₀）', 'Initial ensemble perturbation ε (log₁₀)'), -6, 0, 0.25, -2, (v) => fmt(10 ** v)]],
    btn: [[L('干净的数据', 'Clean data'), { noise: 0, lth: -1 }], [L('有噪声', 'Noisy'), { noise: 0.3, lth: -1 }], [L('阈值太低', 'Threshold too low'), { noise: 0.3, lth: -3 }]],
    figs: [['html', L('找回的系数（每一行是一个方程，只列出非零的项）和真值。', 'Recovered coefficients (one row per equation, nonzero terms only) and the true values.')], [0.42, L('x(t)：灰线是真实的轨迹，彩色细线是用找回的方程做的二十个集合成员。', 'x(t): grey is the true trajectory, thin coloured lines are twenty ensemble members run with the recovered equations.')], [0.34, L('集合的离散度（x 的标准差，对数坐标）；虚线是按最大李雅普诺夫指数 λ ≈ 0.906 增长的斜率。', 'Ensemble spread (standard deviation of x, log scale); the dashed line grows with the largest Lyapunov exponent λ ≈ 0.906.')]],
    note: L('σ = 10、ρ = 28、β = 8/3，RK4，Δt = 0.002，5000 步。导数用五点中心差分，库是到二次的十个单项式，STLSQ（序列阈值最小二乘，Brunton 等 2016）迭代十次。噪声大时差分把噪声放大，阈值太低会留下很多假项；实际中要先平滑或者用积分形式。集合预报：起点是轨迹的起点加 ε × 标准正态，Δt = 0.01，积分 15 个时间单位。', 'σ = 10, ρ = 28, β = 8/3, RK4, Δt = 0.002, 5000 steps. Derivatives by five-point central differences, a library of ten monomials up to second order, STLSQ (sequentially thresholded least squares, Brunton et al. 2016) iterated ten times. With strong noise, differencing amplifies it, and too low a threshold leaves many spurious terms; in practice one smooths first or uses an integral formulation. Ensemble: starting points are the trajectory’s start plus ε × standard normal, Δt = 0.01, integrated for 15 time units.'),
    draw(s, [tv, xv, sv], c) {
      const fit_ = memo(s, 's', `${s.noise}|${s.lth}`, () => M.sindy({ noise: s.noise, thresh: 10 ** s.lth }));
      const eq = ['ẋ', 'ẏ', 'ż'], term = (coef) => coef.map((v, k) => (v ? `${v < 0 ? '−' : '+'} ${fix(Math.abs(v), 3)} ${M.LIB_NAMES[k] === '1' ? '' : M.LIB_NAMES[k]}` : '')).filter(Boolean).join(' ').replace(/^\+ /, '') || '0';
      tv.innerHTML = `<table class="mdf-peaks"><thead><tr><th></th><th>${esc(L('找回的', 'Recovered'))}</th><th>${esc(L('真实的', 'True'))}</th></tr></thead><tbody>${fit_.Xi.map((row, d) => `<tr><td>${eq[d]} =</td><td>${esc(term(row))}</td><td>${esc(term(M.LZ_TRUE[d]))}</td></tr>`).join('')}</tbody></table>`;
      const f = M.sindyF(fit_.Xi), eps = 10 ** s.leps;
      const E = memo(s, 'e', `${s.noise}|${s.lth}|${s.leps}`, () => ({ ens: M.ensembleForecast(f, [-8, 7, 27], { eps, n: 1500, M: 20 }), truth: M.lorenzTraj([-8, 7, 27], 0.01, 1500) }));
      const ts = E.truth.map((_, i) => i * 0.01), pal = [c.accent, c.info, c.violet, c.gold];
      plot(xv, { x: [0, 15], y: [-25, 25], xl: L('时间', 'time'), yl: 'x', series: [...E.ens.map((e, j) => ({ xs: ts.slice(0, e.length), ys: e.map((p) => p[0]), color: pal[j % 4], width: 0.9, alpha: 0.7 })), { xs: ts, ys: E.truth.map((p) => p[0]), color: c.muted, width: 2.4 }] });
      const spread = ts.map((_, i) => { const v = E.ens.map((e) => (e[i] ? e[i][0] : NaN)).filter(Number.isFinite); return v.length > 2 ? Math.max(1e-8, Math.sqrt(M.variance(v))) : NaN; });
      const s0 = eps;
      plot(sv, { x: [0, 15], y: [Math.floor(lg(eps)) - 0.5, 1.5], logy: true, xl: L('时间', 'time'), yl: L('离散度', 'spread'), series: [{ xs: ts, ys: spread, color: c.accent, width: 2 }, { xs: ts, ys: ts.map((t) => s0 * Math.exp(0.906 * t)), color: c.muted, dash: [5, 4], width: 1.4 }], hmarks: [{ y: 1, color: c.gold }] });
      const nz = fit_.Xi.flat().filter((v) => v !== 0).length, maxErr = Math.max(...fit_.Xi.flat().map((v, i) => Math.abs(v - M.LZ_TRUE.flat()[i])));
      const tp = ts[spread.findIndex((v) => v > 1)];
      return [[L('找到的非零项（真实 7 项）', 'Nonzero terms found (true: 7)'), String(nz), true], [L('系数的最大误差', 'Largest coefficient error'), fmt(maxErr)], [L('离散度超过 1 的时刻', 'Time the spread exceeds 1'), tp !== undefined ? fix(tp, 1) : '> 15'], [L('理论估计 ln(1/ε)/λ', 'Estimate ln(1/ε)/λ'), fix(Math.log(1 / eps) / 0.906, 1)]];
    },
  };

  // ── 11. 学出来的分子动力学传播器 ─────────────────────────────────────────
  DEMOS.prop = {
    title: L('学一个“大步长”的分子动力学：一步跨过 τ，快了，但对吗？', 'Learn a “big-step” molecular dynamics: one step spans τ — faster, but is it right?'), kind: 'experiment',
    intro: L('Timewarp、ITO、MDGen 这类模型想做的是分子动力学的世界模型：给一个构型，直接生成 τ 时间以后的构型，一步顶几千步积分。这里在一维双势阱里用最小的版本：从很多条只有一个 τ 长的短轨迹里，拟合一个条件高斯 p(x′ | x)（x′ 是 τ 以后的位置，均值和方差都是 x 的多项式），然后只用它一步一步地跑很长的轨迹，看平衡分布和跨越势垒的平均时间对不对。τ 小时它又快又准；τ 大到能跨过势垒时，真实的条件分布有两个峰，一个高斯装不下，平衡分布和速率都会错。所以 Timewarp 用正规化流、ITO 用扩散模型来表示这个条件分布，Timewarp 还用 Metropolis 校正保证平衡分布是对的。', 'Models such as Timewarp, ITO and MDGen aim at a world model of molecular dynamics: given a configuration, generate the configuration a time τ later in one go, one step replacing thousands of integration steps. Here is the smallest version, in a one-dimensional double well: from many short trajectories, each only τ long, we fit a conditional Gaussian p(x′ | x) (x′ is the position after τ; mean and variance both polynomials in x), then run a very long trajectory with it alone and check the equilibrium distribution and the mean time to cross the barrier. For small τ it is fast and accurate; once τ is long enough to cross the barrier, the true conditional distribution has two peaks, one Gaussian cannot hold them, and both the equilibrium distribution and the rate go wrong. That is why Timewarp uses a normalising flow and ITO a diffusion model for this conditional distribution, and why Timewarp adds a Metropolis correction to guarantee the right equilibrium distribution.'),
    ctl: [['ltau', L('一步跨过的时间 τ', 'Time spanned by one step τ'), -2, 0.3, 0.05, -1.3, (v) => fix(10 ** v, 3)], ['h', L('势垒高度 h（kT）', 'Barrier height h (kT)'), 1, 4, 0.25, 2.5, (v) => v.toFixed(2)], ['n', L('训练用的短轨迹条数', 'Short training trajectories'), 500, 6000, 250, 3000, String]],
    btn: [[L('τ 小：准', 'Small τ: accurate'), { ltau: -1.3 }], [L('τ 和跨垒时间相当', 'τ comparable to the crossing time'), { ltau: 0 }]],
    act: [[L('换一组随机数', 'New random numbers'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.42, L('学到的传播器跑出来的平衡分布（柱子）和玻尔兹曼分布（金线）；灰线是势 U(x)。', 'Equilibrium distribution from the learned propagator (bars) and the Boltzmann distribution (gold); grey is the potential U(x).')], [0.38, L('从 x = −1 出发走一个 τ：真实的分布（柱子，2000 条模拟）和学到的高斯（蓝线）。', 'One step of τ from x = −1: the true distribution (bars, 2000 simulations) and the learned Gaussian (blue).')]],
    note: L('过阻尼 Langevin，kT = D = 1，U = h(x² − 1)²，Euler–Maruyama，Δt = 10⁻³。训练：起点在 [−2.2, 2.2] 均匀撒（不是平衡分布，就像实际中从许多结构出发的短模拟），每条只跑一个 τ。模型：μ(x) 是 7 次多项式；ln σ²(x) 对残差平方的对数做 7 次多项式回归（加 1.27 修正 ln χ² 的偏差）。长轨迹走 4000 个时间单位，状态夹在 [−2.2, 2.2]。精确的平均首次通过时间来自 Smoluchowski 方程的二重积分。τ 很小时误差也会变大：每一步的统计误差累积了 4000/τ 步，这是“步子越小、要的数据越多”。', 'Overdamped Langevin, kT = D = 1, U = h(x² − 1)², Euler–Maruyama, Δt = 10⁻³. Training: starting points uniform in [−2.2, 2.2] (not the equilibrium distribution, as for real short simulations started from many structures), each run for one τ. Model: μ(x) a degree-7 polynomial; ln σ²(x) a degree-7 regression of the log squared residual (plus 1.27 to correct the bias of ln χ²). The long trajectory covers 4000 time units with the state clamped to [−2.2, 2.2]. The exact mean first-passage time comes from the double integral of the Smoluchowski equation. Errors also grow when τ is very small: the statistical error of each step accumulates over 4000/τ steps — smaller steps need more data.'),
    draw(s, [hv, cv], c) {
      const tau = 10 ** s.ltau, key = `${s.ltau}|${s.h}|${s.n}|${s.seed}`;
      const m = memo(s, 'm', key, () => M.propFit(M.propData({ h: s.h, tau, n: s.n, seed: s.seed })));
      const run = memo(s, 'r', key, () => M.propRun(m, -1, Math.round(4000 / tau), M.rng(s.seed + 11)));
      const edges = lin(-2, 2, 41), B = M.boltzHist(s.h, edges), H = M.hist(run, edges), mids = edges.slice(0, -1).map((x) => x + 0.05), top = Math.max(...B, ...H) * 1.15;
      const xs = lin(-2, 2, 200), Umax = Math.max(...xs.map((x) => M.dwU(x, s.h)));
      plot(hv, { x: [-2, 2], y: [0, top], xl: 'x', yl: L('概率', 'probability'), series: [{ xs: xs, ys: xs.map((x) => (M.dwU(x, s.h) <= 2 * s.h ? (M.dwU(x, s.h) / (2 * s.h)) * top * 0.9 : NaN)), color: c.muted, width: 1.4 }, { xs: mids, ys: H, bars: 0.09, color: c.accent, alpha: 0.45, base: 0 }, { xs: mids, ys: B, color: c.gold, width: 2.4 }] });
      const cond = memo(s, 'c', `${s.ltau}|${s.h}|${s.seed}`, () => { const R = M.rng(s.seed + 3), k = Math.max(1, Math.round(tau / 1e-3)); return Array.from({ length: 2000 }, () => M.dwSim(-1, s.h, 1e-3, k, R, k)[0]); });
      const ce = lin(-2.4, 2.4, 49), ch = M.hist(cond, ce), cw = ce[1] - ce[0], mu = m.mu(-1), sd = m.sd(-1), gx = lin(-2.4, 2.4, 300), g = gx.map((x) => (cw * Math.exp(-0.5 * ((x - mu) / sd) ** 2)) / (sd * Math.sqrt(2 * Math.PI)));
      plot(cv, { x: [-2.4, 2.4], y: [0, Math.max(...ch, ...g) * 1.15], xl: L('τ 以后的位置', 'position after τ'), series: [{ xs: ce.slice(0, -1).map((x) => x + cw / 2), ys: ch, bars: cw * 0.9, color: c.muted, alpha: 0.5, base: 0 }, { xs: gx, ys: g, color: c.info, width: 2.2 }] });
      const ex = memo(s, 'x', String(s.h), () => M.mfptExact(s.h)), mf = M.mfptFromTraj(run, tau);
      return [[L('一步顶几步积分', 'Integration steps per model step'), fmt(Math.round(tau / 1e-3))], [L('平衡分布的 L1 误差', 'L1 error of the equilibrium distribution'), fix(M.l1(H, B), 3), true], [L('跨垒的平均时间：精确 / 学到的', 'Mean barrier-crossing time: exact / learned'), `${fix(ex, 2)} / ${Number.isFinite(mf.t) ? fix(mf.t, 2) : '—'}`], [L('长轨迹里跨垒的次数', 'Crossings in the long trajectory'), String(mf.n)]];
    },
  };

  // ── 12. 反应的世界模型：机理模型、高斯过程和随机试 ─────────────────────────
  const RXS = [['mech', L('机理模型（灰箱）', 'Mechanistic model (grey box)'), L('机理', 'Mechanistic')], ['gp', L('高斯过程 + EI（黑箱）', 'Gaussian process + EI (black box)'), L('高斯过程', 'GP + EI')], ['random', L('随机试', 'Random'), L('随机', 'Random')]];
  DEMOS.rxopt = {
    title: L('反应的世界模型：知道机理的模型，几次实验就找到最佳条件', 'A world model of a reaction: a model that knows the mechanism finds the best conditions in a few experiments'), kind: 'experiment',
    intro: L('连串反应 A → B → C，想要的是中间体 B；温度高反应快但 B 也分解得快，时间长转化多但 B 也会变成 C。三种自驱实验室的“大脑”各做 n 次实验：随机试；黑箱的高斯过程，用期望提升（EI）挑下一个条件；灰箱的机理模型，假定两步都是 Arrhenius 一级反应，从已有的产率拟合两个速率常数和两个活化能，再去它预测最好的地方做。三种方法的前三次实验一模一样。机理模型这个“世界模型”带着化学知识，往往六七次就到最优；黑箱什么都不假设，要多做；随机试最慢。代价是：机理假设错了，灰箱会很自信地错。', 'In the consecutive reaction A → B → C the product we want is the intermediate B; higher temperature is faster but B also decomposes faster, longer times convert more A but more B turns into C. Three “brains” of a self-driving lab each run n experiments: random trials; a black-box Gaussian process that picks the next condition by expected improvement (EI); and a grey-box mechanistic model that assumes both steps are first-order Arrhenius reactions, fits two rate constants and two activation energies to the yields so far, and goes where it predicts the best. All three share the first three experiments. The mechanistic “world model” carries chemical knowledge and often reaches the optimum in six or seven experiments; the black box assumes nothing and needs more; random trials are slowest. The price: if the mechanistic assumption is wrong, the grey box will be confidently wrong.'),
    sel: [['show', L('左图显示哪一种', 'Shown on the left'), RXS, 'mech']],
    ctl: [['n', L('实验次数', 'Number of experiments'), 4, 20, 1, 12, String], ['noise', L('产率的测量噪声', 'Measurement noise on yield'), 0, 0.06, 0.005, 0.02, (v) => pct(v, 1)]],
    act: [[L('换一组随机数', 'New random numbers'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.62, L('真实的 B 产率随温度和时间的变化（颜色越深越高，时间是对数坐标）；数字是实验的顺序，★ 是真正的最优条件。', 'True yield of B against temperature and time (darker is higher, time on a log scale); numbers give the order of experiments, ★ is the true optimum.')], [0.4, L('到第 k 次实验为止，做过的最好那次的真实产率。', 'True yield of the best experiment so far, after k experiments.')]],
    note: L('k₁(350 K) = 0.05 min⁻¹、Eₐ₁ = 60 kJ/mol，k₂(350 K) = 0.012 min⁻¹、Eₐ₂ = 95 kJ/mol；T ∈ [300, 400] K，t ∈ [1, 120] min（对数）；[B] = k₁/(k₂ − k₁)(e^{−k₁t} − e^{−k₂t})。最优在 t = 120 min 的边界上（时间允许得越长，能用的温度越低、越有选择性）。高斯过程：平方指数核，长度 0.22（在单位方格里），固定的超参数，在 31 × 31 的格点上找 EI 最大的点。机理模型：四个参数用带阻尼的 Gauss–Newton，从四个起点各拟一次。真实的反应优化（Shields 等 2021）是几十维的离散加连续空间，黑箱方法在那里更有用；而这里的对比说明，能写下机理的地方，先验知识就是最便宜的数据。', 'k₁(350 K) = 0.05 min⁻¹, Eₐ₁ = 60 kJ/mol; k₂(350 K) = 0.012 min⁻¹, Eₐ₂ = 95 kJ/mol; T ∈ [300, 400] K, t ∈ [1, 120] min (log scale); [B] = k₁/(k₂ − k₁)(e^{−k₁t} − e^{−k₂t}). The optimum lies on the t = 120 min boundary (the longer the time allowed, the lower and more selective the usable temperature). Gaussian process: squared-exponential kernel, length 0.22 (in the unit square), fixed hyperparameters, EI maximised on a 31 × 31 grid. Mechanistic model: the four parameters by damped Gauss–Newton from four starting points. Real reaction optimisation (Shields et al. 2021) is a space of dozens of discrete and continuous dimensions where black-box methods are more useful; the contrast here shows that where a mechanism can be written down, prior knowledge is the cheapest data.'),
    draw(s, [mv, bv], c) {
      const runs = memo(s, 'r', `${s.n}|${s.noise}|${s.seed}`, () => Object.fromEntries(RXS.map(([k]) => [k, M.rxCampaign(k, { n: s.n, seed: s.seed, noise: s.noise })])));
      const run = runs[s.show];
      plot(mv, { x: [300, 400], y: [0, 1], yt: [1, 10, 100].map((t) => M.toUnit(350, t)[1]), yf: (u) => String(Math.round(M.fromUnit([0, u])[1])), xl: L('温度 T / K', 'temperature T / K'), yl: L('时间 / min', 'time / min'), after: ({ ctx, X, Y }) => {
        const n = 40; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) { const u = [(i + 0.5) / n, (j + 0.5) / n], [T, t] = M.fromUnit(u), y = M.yieldB(T, t); ctx.globalAlpha = Math.max(0.03, y / M.rxBest.y) * 0.75; ctx.fillStyle = c.accent; ctx.fillRect(X(300 + (100 * i) / n), Y((j + 1) / n), X(300 + 100 / n) - X(300) + 1, Y(0) - Y(1 / n) + 1); }
        ctx.globalAlpha = 1; ctx.font = font(11, 700); ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        run.X.forEach((u, k) => { const px = X(300 + 100 * u[0]), py = Y(u[1]); ctx.fillStyle = c.paper; ctx.beginPath(); ctx.arc(px, py, 8, 0, 2 * Math.PI); ctx.fill(); ctx.strokeStyle = k < 3 ? c.muted : c.gold; ctx.lineWidth = 1.6; ctx.stroke(); ctx.fillStyle = c.ink; ctx.fillText(String(k + 1), px, py + 0.5); });
        ctx.fillStyle = c.danger; ctx.font = font(16, 700); ctx.fillText('★', X(300 + 100 * M.rxBest.u[0]), Y(Math.min(0.97, M.rxBest.u[1]))); ctx.textBaseline = 'alphabetic';
      } });
      const ks = run.X.map((_, i) => i + 1), col = { mech: c.accent, gp: c.info, random: c.muted };
      plot(bv, { x: [1, s.n], y: [0, M.rxBest.y * 1.1], xl: L('第几次实验', 'experiment number'), yl: L('最好的产率', 'best yield'), series: RXS.map(([k, , short]) => ({ xs: ks, ys: runs[k].bestSoFar, color: col[k], width: k === s.show ? 2.6 : 1.6, dots: 2.5, line: true, label: short })), hmarks: [{ y: M.rxBest.y, color: c.danger }] });
      const m = s.show === 'mech' ? M.mechFit(run.X, run.y) : null;
      const hit = (r) => { const i = r.bestSoFar.findIndex((v) => v >= 0.97 * M.rxBest.y); return i < 0 ? L('没到', 'not reached') : L(`第 ${i + 1} 次`, `experiment ${i + 1}`); };
      return [[L('真正的最优产率', 'True optimum yield'), pct(M.rxBest.y)], [L('机理 / 高斯过程 / 随机：最好的产率', 'Mechanistic / GP / random: best yield'), RXS.map(([k]) => pct(runs[k].bestSoFar[s.n - 1], 0)).join(' / '), true], [L('到最优的 97 %：机理 / 高斯过程 / 随机', 'Reaching 97 % of optimum: mechanistic / GP / random'), RXS.map(([k]) => hit(runs[k])).join(' / ')], ...(m ? [[L('机理模型拟合的 Eₐ₁ / Eₐ₂（真值 60 / 95 kJ/mol）', 'Fitted Eₐ₁ / Eₐ₂ (true 60 / 95 kJ/mol)'), `${fix(m.th[1] * 10, 0)} / ${fix(m.th[3] * 10, 0)}`]] : [])];
    },
  };

  // ── 13. 什么时候该相信模型：集成的分歧 ──────────────────────────────────
  DEMOS.ens = {
    title: L('什么时候该相信世界模型：几个模型一起投票，分歧就是不确定度', 'When to trust a world model: let several models vote, and their disagreement is the uncertainty'), kind: 'experiment',
    intro: L('一个一维的“世界”：速度场 dx/dt = f(x)。我们只在中间一段有数据，用自助法（每次有放回地重抽样本）训练几个随机特征回归模型。在有数据的地方它们几乎重合；离开数据，它们各自乱猜，分歧变大，而分歧和真实误差高度相关。下面用每个成员从同一个起点推演：起点在数据里时，成员们一起走，走出数据区以后开始分叉。PETS、MBPO 和自驱实验室的主动学习都靠这个信号：分歧小的推演可以用，分歧大的地方要么少信，要么就去做实验或者算一次 DFT。', 'A one-dimensional “world”: a velocity field dx/dt = f(x). We have data only in the middle and train several random-feature regressions by the bootstrap (resampling the data with replacement each time). Where there are data they almost coincide; away from the data each guesses on its own, they disagree more, and the disagreement tracks the true error closely. Below, each member rolls out from the same start: while the start is inside the data the members move together, and they fork once they leave it. PETS, MBPO and active learning in self-driving labs all rely on this signal: rollouts with little disagreement can be used, and where the disagreement is large you either trust less or go and run an experiment — or a DFT calculation.'),
    ctl: [['wd', L('数据的范围 |x| ≤', 'Data range |x| ≤'), 0.3, 2.5, 0.05, 1, (v) => v.toFixed(2)], ['M', L('集成的成员数', 'Ensemble members'), 2, 10, 1, 6, String], ['x0', L('推演的起点 x₀', 'Rollout start x₀'), -3, 3, 0.05, 0.4, (v) => v.toFixed(2)]],
    btn: [[L('数据很窄', 'Narrow data'), { wd: 0.5 }], [L('数据很宽', 'Wide data'), { wd: 2.4 }]],
    act: [[L('换一组数据', 'New data'), (s) => { s.seed = (s.seed || 1) + 1; }]],
    state: () => ({ seed: 1 }),
    figs: [[0.45, L('f(x)：灰线是真实的，彩色细线是各个成员，带子是成员平均 ±2 倍标准差，点是数据，金色是有数据的区域。', 'f(x): grey is the truth, thin coloured lines the members, the band their mean ±2 standard deviations, dots the data, gold the region with data.')], [0.4, L('从 x₀ 出发的推演：灰线是真实的，彩色细线是每个成员。', 'Rollouts from x₀: grey is the truth, thin coloured lines each member.')]],
    note: L('f(x) = sin 2x − 0.3x，40 个数据点，噪声 0.05。每个成员：30 个随机傅里叶特征 cos(wx + b)（w ~ N(0, 1.5²)，b 均匀），岭回归（λ = 10⁻³），在一份自助样本上拟合。推演用 RK4，Δt = 0.05，40 个时间单位。深度集成（Lakshminarayanan 等 2017）在神经网络上做的是同一件事；它测到的是“认识上的不确定度”（模型不知道），测不到数据本身的噪声，也不保证在离数据很远的地方仍然可靠：所有成员可能一起错。', 'f(x) = sin 2x − 0.3x, 40 data points, noise 0.05. Each member: 30 random Fourier features cos(wx + b) (w ~ N(0, 1.5²), b uniform), ridge regression (λ = 10⁻³) on one bootstrap sample. Rollouts by RK4, Δt = 0.05, for 40 time units. Deep ensembles (Lakshminarayanan et al. 2017) do the same thing with neural networks; they measure “epistemic” uncertainty (what the model does not know), not the noise in the data itself, and they are not guaranteed to stay reliable far from the data: all members can be wrong together.'),
    draw(s, [fv, rv], c) {
      const E = memo(s, 'e', `${s.wd}|${s.M}|${s.seed}`, () => M.ensFit({ lo: -s.wd, hi: s.wd, M: s.M, seed: s.seed }));
      const xs = lin(-3, 3, 241), st = xs.map((x) => M.ensStats(E, x)), pal = [c.accent, c.info, c.violet, c.gold, c.ok, c.danger];
      plot(fv, { x: [-3, 3], y: [-3, 3], xl: 'x', yl: 'f(x)', bands: [{ x0: -s.wd, x1: s.wd, color: c.gold, alpha: 0.12 }], series: [...E.members.map((f, j) => ({ xs, ys: xs.map((x) => Math.max(-5, Math.min(5, f(x)))), color: pal[j % pal.length], width: 0.9, alpha: 0.7 })), { xs, ys: xs.map(M.fTrue), color: c.muted, width: 2.6 }, { xs: E.xs, ys: E.ys, dots: 2.4, color: c.ink2 }], after: ({ ctx, X, Y }) => { ctx.globalAlpha = 0.14; ctx.fillStyle = c.info; ctx.beginPath(); st.forEach((q, i) => ctx[i ? 'lineTo' : 'moveTo'](X(xs[i]), Y(Math.min(5, q.mean + 2 * q.sd)))); for (let i = st.length - 1; i >= 0; i--) ctx.lineTo(X(xs[i]), Y(Math.max(-5, st[i].mean - 2 * st[i].sd))); ctx.closePath(); ctx.fill(); ctx.globalAlpha = 1; } });
      const n = 800, ts = lin(0, 40, n + 1), truth = M.ensRollout(M.fTrue, s.x0, 0.05, n), rolls = E.members.map((f) => M.ensRollout(f, s.x0, 0.05, n));
      plot(rv, { x: [0, 40], y: [-3.5, 3.5], xl: L('时间', 'time'), yl: 'x(t)', hbands: [{ y0: -s.wd, y1: s.wd, color: c.gold, alpha: 0.12 }], series: [...rolls.map((r, j) => ({ xs: ts.slice(0, r.length), ys: r, color: pal[j % pal.length], width: 1, alpha: 0.8 })), { xs: ts, ys: truth, color: c.muted, width: 2.4 }] });
      const inside = st.filter((_, i) => Math.abs(xs[i]) <= s.wd), outside = st.filter((_, i) => Math.abs(xs[i]) > s.wd + 0.3);
      const fork = ts.findIndex((_, i) => { const v = rolls.map((r) => r[i]).filter(Number.isFinite); return v.length < rolls.length || Math.max(...v) - Math.min(...v) > 0.3; });
      return [[L('分歧和真实误差的相关系数', 'Correlation of disagreement with true error'), fix(M.corr(st.map((q) => q.sd), st.map((q) => q.err)), 2), true], [L('平均分歧：数据里 / 数据外', 'Mean disagreement: inside / outside the data'), `${fmt(M.mean(inside.map((q) => q.sd)))} / ${outside.length ? fmt(M.mean(outside.map((q) => q.sd))) : '—'}`], [L('成员们开始分叉的时刻（相差 > 0.3）', 'Time the members fork (spread > 0.3)'), fork < 0 ? L('到 t = 40 都没有分叉', 'none up to t = 40') : fix(ts[fork], 1)]];
    },
  };
};
